definition.script:
var numInput = input.get('number');
var formatType = input.get('format') || 'number';
var decimals = parseInt(input.get('decimals') || '2');
var currencySymbol = input.get('currencySymbol') || '$';
var thousandsSep = input.get('thousandsSeparator') || ',';
var decimalSep = input.get('decimalSeparator') || '.';
var prefix = input.get('prefix') || '';
var suffix = input.get('suffix') || '';

if (numInput === null || numInput === undefined || numInput === '') {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Number input is required');
    tags.trigger('error');
} else {
    try {
        var num = parseFloat(numInput);
        if (isNaN(num)) throw new Error('Invalid number');

        var result = '';
        var absNum = Math.abs(num);
        var sign = num < 0 ? '-' : '';

        function addThousands(n) {
            var parts = n.toString().split('.');
            var intPart = parts[0];
            var formatted = '';
            var count = 0;
            for (var i = intPart.length - 1; i >= 0; i--) {
                if (count > 0 && count % 3 === 0) formatted = thousandsSep + formatted;
                formatted = intPart.charAt(i) + formatted;
                count++;
            }
            if (parts.length > 1) formatted += decimalSep + parts[1];
            return formatted;
        }

        switch (formatType) {
            case 'currency':
                var fixed = absNum.toFixed(decimals);
                result = sign + currencySymbol + addThousands(fixed);
                break;

            case 'percent':
                result = (num * 100).toFixed(decimals) + '%';
                break;

            case 'percentRaw':
                result = num.toFixed(decimals) + '%';
                break;

            case 'compact':
                var abbrev = '';
                var compactNum = absNum;
                if (absNum >= 1e12) { compactNum = absNum / 1e12; abbrev = 'T'; }
                else if (absNum >= 1e9) { compactNum = absNum / 1e9; abbrev = 'B'; }
                else if (absNum >= 1e6) { compactNum = absNum / 1e6; abbrev = 'M'; }
                else if (absNum >= 1e3) { compactNum = absNum / 1e3; abbrev = 'K'; }
                result = sign + compactNum.toFixed(decimals).replace(/\.0+$/, '').replace(/(\.[0-9]*[1-9])0+$/, '$1') + abbrev;
                break;

            case 'scientific':
                result = num.toExponential(decimals);
                break;

            case 'ordinal':
                var absInt = Math.abs(Math.round(num));
                var suffix_ord = 'th';
                if (absInt % 100 < 11 || absInt % 100 > 13) {
                    if (absInt % 10 === 1) suffix_ord = 'st';
                    else if (absInt % 10 === 2) suffix_ord = 'nd';
                    else if (absInt % 10 === 3) suffix_ord = 'rd';
                }
                result = sign + absInt + suffix_ord;
                break;

            case 'bytes':
                var units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
                var unitIdx = 0;
                var bytesNum = absNum;
                while (bytesNum >= 1024 && unitIdx < units.length - 1) {
                    bytesNum /= 1024;
                    unitIdx++;
                }
                result = sign + bytesNum.toFixed(decimals).replace(/\.0+$/, '') + ' ' + units[unitIdx];
                break;

            case 'number':
            default:
                result = sign + addThousands(absNum.toFixed(decimals));
                break;
        }

        result = prefix + result + suffix;

        output.set('Result', result);
        output.set('OriginalNumber', num);
        output.set('AbsoluteValue', absNum);
        output.set('IsPositive', num > 0);
        output.set('IsNegative', num < 0);
        output.set('IsZero', num === 0);
        output.set('IsInteger', num % 1 === 0);
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('Formatted: ' + num + ' -> ' + result);
        tags.trigger('success');

    } catch (ex) {
        log.error('Format failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        tags.trigger('error');
    }
}
